import "server-only";

import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

import { env } from "@/lib/env";

/**
 * Private object storage. Keys are always generated by the server; the pattern below rejects
 * anything else, so user input can never become a path. Objects are never served directly —
 * only through authorized route handlers.
 */
export interface ObjectStorage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^[a-z0-9]+(?:\/[a-z0-9-]+)*\.[a-z0-9]+$/;

export function assertSafeKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.length > 200) throw new Error("Invalid storage key");
}

/** Development/test driver: files under .storage/ (gitignored, outside public/). */
export class LocalDiskStorage implements ObjectStorage {
  private readonly root: string;

  constructor(root = ".storage") {
    // Runtime-only path (dev/test driver); tell Turbopack not to trace the project from it.
    this.root = resolve(/* turbopackIgnore: true */ root);
  }

  private path(key: string): string {
    assertSafeKey(key);
    const full = resolve(/* turbopackIgnore: true */ join(this.root, key));
    if (!full.startsWith(this.root + sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, body: Buffer, _contentType: string): Promise<void> {
    const path = this.path(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, body);
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.path(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }
}

let storage: ObjectStorage | undefined;

export function getStorage(): ObjectStorage {
  if (storage) return storage;
  if (env().STORAGE_DRIVER === "local") {
    storage = new LocalDiskStorage();
    return storage;
  }
  // A private cloud bucket is configured before production (Task 021).
  throw new Error("No object storage is configured (STORAGE_DRIVER=disabled).");
}
